package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Entry is a single ledger entry.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// Column widths used when rendering the table.
const (
	dateWidth        = 10
	descriptionWidth = 25
	changeWidth      = 13
)

// FormatLedger formats the given entries into a ledger table for the supplied
// currency ("USD" or "EUR") and locale ("en-US" or "nl-NL").
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if _, err := currencySymbol(currency); err != nil {
		return "", err
	}
	if locale != "en-US" && locale != "nl-NL" {
		return "", errors.New("invalid locale")
	}

	// Sort a copy so the caller's slice is never mutated.
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		a, b := sorted[i], sorted[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})

	var b strings.Builder
	b.WriteString(header(locale))
	for _, e := range sorted {
		line, err := formatRow(currency, locale, e)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// header renders the table's header line for the given locale.
func header(locale string) string {
	var dateHeader, descHeader, changeHeader string
	switch locale {
	case "nl-NL":
		dateHeader, descHeader, changeHeader = "Datum", "Omschrijving", "Verandering"
	default: // en-US
		dateHeader, descHeader, changeHeader = "Date", "Description", "Change"
	}
	return padRight(dateHeader, dateWidth) + " | " +
		padRight(descHeader, descriptionWidth) + " | " +
		changeHeader + "\n"
}

// formatRow renders a single ledger row, validating the entry's date.
func formatRow(currency, locale string, e Entry) (string, error) {
	date, err := formatDate(locale, e.Date)
	if err != nil {
		return "", err
	}
	symbol, err := currencySymbol(currency)
	if err != nil {
		return "", err
	}
	var amount string
	if locale == "nl-NL" {
		amount = formatAmountNL(symbol, e.Change)
	} else {
		amount = formatAmountUS(symbol, e.Change)
	}
	return padRight(date, dateWidth) + " | " +
		formatDescription(e.Description) + " | " +
		rightJustify(amount, changeWidth) + "\n"
}

// formatDate converts an "Y-m-d" date into the locale's display format,
// validating its shape along the way.
func formatDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errors.New("invalid date")
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if locale == "nl-NL" {
		return day + "-" + month + "-" + year, nil
	}
	return month + "/" + day + "/" + year, nil
}

// formatDescription pads the description to the column width, truncating
// overlong descriptions with an ellipsis.
func formatDescription(desc string) string {
	if len(desc) > descriptionWidth {
		return desc[:descriptionWidth-3] + "..."
	}
	return padRight(desc, descriptionWidth)
}

// currencySymbol maps a currency code to its display symbol.
func currencySymbol(currency string) (string, error) {
	switch currency {
	case "USD":
		return "$", nil
	case "EUR":
		return "€", nil
	}
	return "", errors.New("invalid currency")
}

// formatAmountUS renders an amount in the American style, e.g. "$1,234.56" or
// "($1,234.56)" for a negative change.
func formatAmountUS(symbol string, change int) string {
	abs, negative := abs(change)
	dollars, cents := abs/100, abs%100
	num := groupThousands(strconv.Itoa(dollars), ",") + "." + twoDigits(cents)
	if negative {
		return "(" + symbol + num + ")"
	}
	return symbol + num + " "
}

// formatAmountNL renders an amount in the Dutch style, e.g. "$ 1.234,56" or
// "$ 1.234,56-" for a negative change.
func formatAmountNL(symbol string, change int) string {
	abs, negative := abs(change)
	dollars, cents := abs/100, abs%100
	num := groupThousands(strconv.Itoa(dollars), ".") + "," + twoDigits(cents)
	if negative {
		return symbol + " " + num + "-"
	}
	return symbol + " " + num + " "
}

// abs returns the absolute value of n and whether it was negative.
func abs(n int) (int, bool) {
	if n < 0 {
		return -n, true
	}
	return n, false
}

// twoDigits renders a value in 0-99 with a leading zero, e.g. 5 -> "05".
func twoDigits(n int) string {
	return fmt.Sprintf("%02d", n)
}

// groupThousands groups a non-negative integer's digits into blocks of three,
// separated by sep, e.g. ("1234567", ",") -> "1,234,567".
func groupThousands(digits string, sep string) string {
	if len(digits) <= 3 {
		return digits
	}
	var groups []string
	for len(digits) > 3 {
		groups = append(groups, digits[len(digits)-3:])
		digits = digits[:len(digits)-3]
	}
	groups = append(groups, digits)
	for i, j := 0, len(groups)-1; i < j; i, j = i+1, j-1 {
		groups[i], groups[j] = groups[j], groups[i]
	}
	return strings.Join(groups, sep)
}

// padRight pads s with spaces on the right up to width.
func padRight(s string, width int) string {
	return s + strings.Repeat(" ", width-len(s))
}

// rightJustify pads s with spaces on the left so it occupies width columns,
// measured in runes so that multi-byte symbols (like €) take a single column.
func rightJustify(s string, width int) string {
	pad := width - utf8.RuneCountInString(s)
	if pad < 0 {
		pad = 0
	}
	return strings.Repeat(" ", pad) + s
}
